package io.ochre.bridge;
import java.util.*;
import static io.ochre.bridge.ActionSupport.*;

/// Real menu-slot operations with a world/menu identity token and normal slot rules.
final class ContainerActions {
 private ContainerActions() { }
 static String token(Object c,Object menu)throws Exception{return world(c)+":"+field(menu,"containerId")+":"+System.identityHashCode(menu);}
 static Object menu(Object c,Map<String,String> request)throws Exception{Object menu=field(player(c),"containerMenu");if(!token(c,menu).equals(request.get("menu_token")))throw new java.io.IOException("container.changed");return menu;}
 static void read(Object c,Map<String,String> request,Map<String,String> result)throws Exception{Object p=player(c),menu=field(p,"containerMenu");List<?> slots=(List<?>)field(menu,"slots");int offset=integer(request,"offset",0,slots.size()),limit=integer(request,"limit",1,24),count=Math.min(limit,slots.size()-offset);result.put("menu_token",token(c,menu));result.put("total",Integer.toString(slots.size()));result.put("count",Integer.toString(count));result.put("offset",Integer.toString(offset));for(int i=0;i<count;i++){Object slot=slots.get(offset+i),stack=call(slot,"getItem");String prefix="slot."+i+".";result.put(prefix+"slot",Integer.toString(offset+i));result.put(prefix+"inventory_slot",call(slot,"getContainerSlot").toString());result.put(prefix+"item",id(call(stack,"getItem")));result.put(prefix+"count",call(stack,"getCount").toString());result.put(prefix+"empty",call(stack,"isEmpty").toString());result.put(prefix+"max_count",slot.getClass().getMethod("getMaxStackSize",type(c,"net.minecraft.world.item.ItemStack")).invoke(slot,stack).toString());result.put(prefix+"accepts_held",Boolean.toString(place(c,slot,call(p,"getMainHandItem"))));result.put(prefix+"may_pickup",slot.getClass().getMethod("mayPickup",type(c,"net.minecraft.world.entity.player.Player")).invoke(slot,p).toString());}}
 private static void click(Object c,Object menu,int slot,int button,String action)throws Exception{if(field(player(c),"containerMenu")!=menu)throw new java.io.IOException("container.changed");Object mode=field(c,"gameMode");Class<?> input=type(c,"net.minecraft.world.inventory.ContainerInput");mode.getClass().getMethod("handleContainerInput",int.class,int.class,int.class,input,type(c,"net.minecraft.world.entity.player.Player")).invoke(mode,((Number)field(menu,"containerId")).intValue(),slot,button,input.getField(action).get(null),player(c));}
 private static boolean pickup(Object c,Object slot)throws Exception{return (Boolean)slot.getClass().getMethod("mayPickup",type(c,"net.minecraft.world.entity.player.Player")).invoke(slot,player(c));}
 private static boolean place(Object c,Object slot,Object stack)throws Exception{return (Boolean)slot.getClass().getMethod("mayPlace",type(c,"net.minecraft.world.item.ItemStack")).invoke(slot,stack);}
 static void act(Object c,Map<String,String> request,Map<String,String> result)throws Exception{Object p=player(c),menu=menu(c,request);List<?> slots=(List<?>)field(menu,"slots");String action=request.getOrDefault("action","");int from=integer(request,"from",0,slots.size()-1);Object source=slots.get(from),stack=call(source,"getItem");if(!pickup(c,source))throw new java.io.IOException("permission.container.pickup.denied");if(action.equals("quick_move")){if(!(Boolean)call(call(menu,"getCarried"),"isEmpty"))throw new java.io.IOException("container.cursor.not.empty");click(c,menu,from,0,"QUICK_MOVE");result.put("status","submitted_to_server");return;}
  int to=integer(request,"to",0,slots.size()-1);if(from==to)throw new java.io.IOException("container.same.slot");Object target=slots.get(to),other=call(target,"getItem");if(!(Boolean)call(call(menu,"getCarried"),"isEmpty"))throw new java.io.IOException("container.cursor.not.empty");if((Boolean)call(stack,"isEmpty"))throw new java.io.IOException("container.source.empty");if(!place(c,target,stack))throw new java.io.IOException("permission.container.place.denied");
  if(action.equals("swap")){if(!(Boolean)call(other,"isEmpty")&&(Boolean)type(c,"net.minecraft.world.item.ItemStack").getMethod("isSameItemSameComponents",type(c,"net.minecraft.world.item.ItemStack"),type(c,"net.minecraft.world.item.ItemStack")).invoke(null,stack,other))throw new java.io.IOException("container.swap.same.items.use.move");if(((Number)target.getClass().getMethod("getMaxStackSize",type(c,"net.minecraft.world.item.ItemStack")).invoke(target,stack)).intValue()<((Number)call(stack,"getCount")).intValue()||((Number)source.getClass().getMethod("getMaxStackSize",type(c,"net.minecraft.world.item.ItemStack")).invoke(source,other)).intValue()<((Number)call(other,"getCount")).intValue())throw new java.io.IOException("container.target.full");if(!pickup(c,target)||!place(c,source,other))throw new java.io.IOException("permission.container.swap.denied");click(c,menu,from,0,"PICKUP");try{click(c,menu,to,0,"PICKUP");click(c,menu,from,0,"PICKUP");}finally{if(field(p,"containerMenu")==menu&&!(Boolean)call(call(menu,"getCarried"),"isEmpty"))click(c,menu,from,0,"PICKUP");}}
  else if(action.equals("move")){int available=((Number)call(stack,"getCount")).intValue(),count=integer(request,"count",0,64);if(count==0)count=available;if(count>available||count>64)throw new java.io.IOException("container.count.invalid");boolean empty=(Boolean)call(other,"isEmpty");if(!empty&&!(Boolean)type(c,"net.minecraft.world.item.ItemStack").getMethod("isSameItemSameComponents",type(c,"net.minecraft.world.item.ItemStack"),type(c,"net.minecraft.world.item.ItemStack")).invoke(null,stack,other))throw new java.io.IOException("container.target.incompatible");int max=((Number)target.getClass().getMethod("getMaxStackSize",type(c,"net.minecraft.world.item.ItemStack")).invoke(target,stack)).intValue();if(max-((Number)call(other,"getCount")).intValue()<count)throw new java.io.IOException("container.target.full");click(c,menu,from,0,"PICKUP");try{if(count==available)click(c,menu,to,0,"PICKUP");else for(int i=0;i<count;i++)click(c,menu,to,1,"PICKUP");}finally{if(field(p,"containerMenu")==menu&&!(Boolean)call(call(menu,"getCarried"),"isEmpty"))click(c,menu,from,0,"PICKUP");}}
  else throw new java.io.IOException("container.action.unsupported");result.put("status","submitted_to_server");
 }
}
